define({"topics":[{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_4.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e41130","topics":[]},{"title":"Logging on and off","shortdesc":"<p class=\"shortdesc\">Use this procedure to log on and off the system.<\/p>","href":"t_UserInstructions_2.html","attributes":{"data-id":"id_2011694"},"menu":{"hasChildren":false},"tocID":"id_2011694-d46e41232","topics":[]},{"title":"<span class=\"ph\">Restarting the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Restarting the host computer safely shuts down and restarts the system. Restarting the system is often required to finalize changes or updates.<\/p>","href":"t_RestartingTheHostComputer.html","attributes":{"data-id":"id_2002040"},"menu":{"hasChildren":false},"tocID":"id_2002040-d46e41334","topics":[]},{"title":"<span class=\"ph\">Shutting down<span class=\"ph\">\/powering off<\/span> the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_Parent_3.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e41437","topics":[]}]});